        val plugin = ActivityFileValidationPlugin()

        try {
            val fitDecoder = FitDecoder()
            fitDecoder.decode(byteArrayInputStream, plugin)
        } catch (e: FitRuntimeException) {
            kotlin.io.println("FitRuntimeException decoding file: " + e.message)
        } catch (e: Exception) {
            kotlin.io.println("Exception decoding file: " + e.message)
        } finally {
            // If an exception occurred before onBroadcast() was called,
            // then the validation checks would not have been executed.
            // There may still be decoded messages that are worth validating,
            // so force the validation checks to execute. Some tests may be
            // skipped or fail.
            if (plugin.getResults().size == 0) {
                plugin.repeatValidation()
            }

            kotlin.io.println("Message Count: " + plugin.mesgCount)

            for (result in plugin.getResults()) {
                println(result)
                if (result!!.description != null) {
                    kotlin.io.println("\t" + result.description)
                }
            }

            byteArrayInputStream.reset()
        }
    }

