                        outputFileName.length
                    ).compareTo(".fit") == 0
                ) {
                    outputFileName = outputFileName.substring(0, outputFileName.length - 4)
                }

                System.out.printf(
                    "Encoding %s into FIT binary file %s.fit.\n",
                    inputFileName,
                    outputFileName
                )
                try {
                    byteStreamFromFile(inputFileName)?.let { stream ->
                        csvTool.convertCsvToFit(stream)
                    }

                } catch (e: Exception) {
                    System.out.printf(
                        "Error: A problem occurred while encoding the file. The encoded FIT file %s.fit may be a truncated.\n",
                        outputFileName
                    )
                    if (e.message != null) {
                        println(e.message)
                    }
                }

                try {
                    val fitByteArrayOutputStream = csvTool.getByteArrayOutputStream()
                    writeByteStreamToFile(fitByteArrayOutputStream, outputFileName + ".fit", false)
                } catch (e: Exception) {
                    println("Error: A problem occurred while writing the output FIT file.")
                }
            } else {
                printUsage()
            }
        }

        private fun printUsage() {
            println("Usage: java -jar FitCSVTool.jar <options> <file>")
            println("      -b <FIT FILE> <CSV FILE>  FIT binary to CSV.")
            println("      -c <CSV FILE> <FIT FILE>  CSV to FIT binary.")
            println("      -t Enable file verification tests.")
            println("      -d Enable debug output.")
            println("      -i Check integrity of FIT file before decoding.")
            println("      -s Show invalid fields in the CSV file.")
            println("      -se Show invalid fields in the CSV file as empty cells.")
            println("      -u Hide unknown data and report statistics on how much is hidden.")
            println("      -x Print byte values as hexadecimal.")
            println("      -deg Print semicircle values as degrees.")
            println("      -iso8601 Print date-time values as ISO 8601 formatted strings.")
            println("      -ex Changes the behaviour of the --defn and --data options to")
            println("          filter out the messages listed. The default behaviour without")
            println("          this flag is to exclude all messages except those listed")
            println("          after the --defn and the --data options.")
            println("      -pN Encode file using Protocol Version <N>. Default: 2")
            println("      -e Print enum values as their corresponding String labels when")
            println("          possible. Note: CSV files generated with this option will not")
            println("          be able to be converted back into .FIT files.")
            println("      -re Remove expanded fields from CSV output. This removes fields")
            println("          that have been generated through component expansion and")
            println("          which do not exist in the source .FIT file")
            println("      --defn <MESSAGE_STRING_0,MESSAGE_STRING_1,...> Narrows down the")
            println("          definitions output to CSV. Use 'none' for no definitions")
            println("          When this option is used only the message definitions")
            println("          in the comma separated list will be written to the CSV.")
            println("          eg. --defn file_capabilities,record,file_creator")
            println("          Note: This option is only compatible with the -b option.")
            println("      --data <MESSAGE_STRING_0,MESSAGE_STRING_1,...> Narrows down the")
            println("          data output to CSV. When this option is used only the data")
            println("          in the comma separated list will be written to the csv.")
            println("          eg. --data file_capabilities,record,file_creator")
            println("          Note: This option is only compatible with the -b option.")
            println("      -g Preserve gaps caused by data dropouts. ")
            println("          Note: This option is only compatible with the --data option")
        }
    }
}

